package io.github.hoangtnedu.java.management;
import io.github.hoangtnedu.java.orders.*;import io.github.hoangtnedu.java.warehouse.WarehouseService;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import org.apache.catalina.startup.Tomcat;import java.nio.file.*;import java.net.*;import java.net.http.*;import java.util.*;
@SpringBootTest @AutoConfigureMockMvc class IntegratedTest {
 static Tomcat customer;static HttpClient client;static String base,csrf,auth;
 static {try{Database.init();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @Autowired MockMvc mvc;@Autowired OrderRepository repo;
 @BeforeAll static void start()throws Exception{customer=new Tomcat();customer.setBaseDir(Files.createTempDirectory("customer").toString());customer.setPort(0);customer.getConnector();var context=customer.addWebapp("",Path.of("../customer/target/customer.war").toAbsolutePath().toString());context.setParentClassLoader(IntegratedTest.class.getClassLoader());customer.start();assertTrue(context.getState().isAvailable());base="http://127.0.0.1:"+customer.getConnector().getLocalPort();client=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();auth="Basic "+Base64.getEncoder().encodeToString(("customer:"+System.getenv().getOrDefault("LAB_DEMO_PASSWORD","change-me-local")).getBytes());var response=client.send(HttpRequest.newBuilder(URI.create(base+"/orders")).header("Authorization",auth).build(),HttpResponse.BodyHandlers.ofString());assertEquals(200,response.statusCode());csrf=response.headers().firstValue("X-CSRF-Token").orElseThrow();}
 @AfterAll static void stop()throws Exception{if(customer!=null){customer.stop();customer.destroy();}}
 static HttpResponse<String> postCustomer(String fields)throws Exception{return client.send(HttpRequest.newBuilder(URI.create(base+"/orders")).header("Authorization",auth).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString("csrf="+csrf+"&"+fields)).build(),HttpResponse.BodyHandlers.ofString());}
 long product(int stock)throws Exception{try(var c=Database.open();var p=c.prepareStatement("INSERT INTO products(code,name,price,stock) VALUES(?,?,10,?)",java.sql.Statement.RETURN_GENERATED_KEYS)){p.setString(1,"SP"+System.nanoTime());p.setString(2,"Demo");p.setInt(3,stock);p.executeUpdate();try(var r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}
 @Test void threePlatformsShareTheSameOrderAndHistory()throws Exception{long product=product(10);var created=postCustomer("product="+product+"&quantity=2");assertEquals(201,created.statusCode());long id=Long.parseLong(created.headers().firstValue("X-Order-Id").orElseThrow());WarehouseService warehouse=new WarehouseService();Database.User user=Database.user("warehouse");assertTrue(warehouse.pending().stream().anyMatch(x->((Number)x[0]).longValue()==id));warehouse.move(user,id,"PROCESSING");assertThrows(java.sql.SQLException.class,()->warehouse.move(user,id,"PROCESSING"));warehouse.move(user,id,"READY");mvc.perform(post("/orders/"+id+"/ship").with(user("manager").roles("MANAGER")).with(csrf())).andExpect(status().is3xxRedirection());assertEquals("SHIPPING",repo.findById(id).orElseThrow().status);assertEquals(200,postCustomer("action=complete&id="+id).statusCode());assertEquals("COMPLETED",repo.findById(id).orElseThrow().status);try(var c=Database.open();var s=c.createStatement()){try(var r=s.executeQuery("SELECT stock FROM products WHERE id="+product)){r.next();assertEquals(8,r.getInt(1));}try(var r=s.executeQuery("SELECT COUNT(*) FROM order_status_history WHERE order_id="+id)){r.next();assertEquals(5,r.getInt(1));}}}
 @Test void insufficientStockRollsBackAndUserCannotApprove()throws Exception{long product=product(1);var created=postCustomer("product="+product+"&quantity=9");long id=Long.parseLong(created.headers().firstValue("X-Order-Id").orElseThrow());assertThrows(java.sql.SQLException.class,()->new WarehouseService().move(Database.user("warehouse"),id,"PROCESSING"));assertEquals("PENDING",repo.findById(id).orElseThrow().status);mvc.perform(post("/orders/"+id+"/ship").with(user("customer").roles("CUSTOMER")).with(csrf())).andExpect(status().isForbidden());try(var c=Database.open();var s=c.createStatement();var r=s.executeQuery("SELECT stock FROM products WHERE id="+product)){r.next();assertEquals(1,r.getInt(1));}}
}